0.550002 -0.442773 | -0.947706 1.725029 0.323857 1.754524 0.137407 1.103011 | -0.267969 -0.337497 -0.406588 -0.258090 0.288291 0.021599 | 0.257031 -0.325730 -0.040853 0.620186 0.531902 -0.041574 | -0.367265 -1.260834 -0.219451 -0.603881 -0.391501 -0.885596 | -0.128555 -0.252603 -0.740628 -0.499267 -0.409164 0.085816 | 0.640031 0.752208 1.533514 0.474417 0.780904 0.582275 | 0.009870 0.008301 0.219376 1.493781 -0.111128 0.374580', '2', 'pca', 'varimax') AS j;
